--{{{初见部分
---添加初见通用属性
---@param type ChuJianSDKType
---@param data table 自定义数据类型 key value形式
---@return table key value形式
function QuickTaHelper:ChuJianExtraAddFields(event,data)
    if data==nil then
        data={}
    end
    if type(event)  == "string" then
        data.ctgr = event
    else
        data.ctgr = self:GetEventNameByChuJianSDKType(event)
    end
    data.uuid= QuickTaDefaultData.umid..tostring(CS.System.DateTime.Now.Ticks)..math.random(0,10)
    data.gusd= QuickTaDefaultData.gusd
    data.usid= QuickTaDefaultData.usid
    data.clid= QuickTaDefaultData.clid
    data.umid= QuickTaDefaultData.umid
    data.crat= HotfixHelper:GetNowTimeForMta()
    data.cchd= QuickTaDefaultData.cchd
    data.cchn= QuickTaDefaultData.cchn
    return data
end

---通过 ChuJianSDKType转化成string
---@param  value ChuJianSDKType
---@return string
function QuickTaHelper:GetEventNameByChuJianSDKType(value)
    for k, v in pairs(ChuJianSDKType) do
        if v == value then
            return tostring(k)
        end
    end
    return "该类型未被定义"
end

--- 获取最后的打点信息
--- @param type  ChuJianSDKType
--- @param data  table  自己设置key value
--- @return table  key value形式
function QuickTaHelper:GetChuJianData(eventname, data)
    local finalData
    if ChuJianSDKType.GameDeviceActiveEvent == eventname then
        finalData = self:ChuJianExtraAddFields(eventname,QuickTAData:GameDeviceActive())
    else
        finalData = self:ChuJianExtraAddFields(eventname,data)
    end
    --if finalData~=nil then
    --    local str = self:TableInverter(finalData)
    --
    --
    --    return str
    --end
    return finalData
end

local function encode_string(val)
    return '"' ..tostring(val).. '"'
end

function QuickTaHelper:TableInverter(t)

    local res={}
    for k, v in pairs(t) do
        if v and type(v) =="table" then
            table.insert(res, encode_string(k) .. ":" ..self:TableInverter(v))
        else
            table.insert(res, encode_string(k) .. ":" ..encode_string(v))
        end
    end
    return "{" .. table.concat(res, ",") .. "}"
end

---发送初见log信息
---@param type ChuJianSDKType or 自定义string类型
---@param data table  Key Value 形式
function QuickTaHelper:ChuJianSendLogServer(event,data)
    local jsonData
    --if ChuJianSDKCustomizedType[event]~=nil then---由于历史原因，需要重新设置一下事件
    --    event=ChuJianSDKCustomizedType[event]
    --end
    try(function()
        jsonData = HotfixHelper:GetChuJianData(event,QuickTaHelper:GetChuJianData(event,data))
        --if type(event)=="string" then
        --    event=ChuJianSDKType.CustomizedEvent
        --end
        HotfixHelper:SendHttpPost_LogServer(jsonData,event,function(data)
            --print("  ChuJianSDK   SendHttpPost_LogServer success    :  ",tostring(data))
        end,function(ERRORCODE)
            if ERRORCODE==7 then
                ERRORCODE ="超时"
            end
            print("  ChuJianSDK   SendHttpGet_LogServer  error    :  ",ERRORCODE)
        end)
    end).catch(function(ex)
        print("   ChuJianSDK.SendLogServer Error",ex)
    end).finally(function()
        if self.IsLog then
            if jsonData then
                print("  ChuJianSDK jsonData",jsonData)
            end
        end
    end)
end
