---@param guideId number @引导id
function QuickTaHelper:TrackNewStagesEvent(guideId,dur_time,type)
    local level = PlayerDataManager:Get():GetPlayerLV()
    local last_trigger_time =GuideManager:Get():GetLastTriggerTime()
    local interval_time=-1;
    local trigger_time = CS.ServerTime:Get():ServerTimeNow()
    local dur_time=dur_time and dur_time or 0
    local type=  type and type or "Normal"
    local guide1=1
    if ClientDataManager:Get().IsConfig2 then
        guide1=2
    end
    if last_trigger_time ~= nil then
        GuideManager:Get():SetLastTriggerTime(trigger_time);
        interval_time =CS.ServerTime:Get():ConvertDateTimeInt(trigger_time) -  CS.ServerTime:Get():ConvertDateTimeInt(last_trigger_time)
    else
        GuideManager:Get():SetLastTriggerTime(trigger_time);
    end
    ---@type GetNewStages data
    local data= QuickTaData:GetNewStages(guideId,level,interval_time,dur_time,type,guide1)
    QuickTa:Get():TrackEvent(TrackEventNames.NewStages,data)
end

