---@param type string @ 配件改造成功/配件重铸成功/配件强化成功
---@param msg SC_RefromPart
---@param oldNum number @之前的数值
---@param newNum number @变化后的数值
function  QuickTaHelper:TrackPartReformEvent(type,msg,oldNum,newNum)
    try( function()
        local alter_val = oldNum~=nil and newNum-oldNum or oldNum
        ---@type ArticleCell
        local data = KnapsackDataManager:Get():GetArticleByID(msg.curPart.partinx)
        local index
        for i = 1, #msg.curPart.curEntry do
            ---@type PartReformData
            local partReformData= data:GetPartReformByEntryId(msg.curPart.curEntry[i].entryid)
            if type=="配件改造成功" then
                if partReformData == nil then
                    index=i
                    break
                end
            elseif type=="配件重铸成功" then
                if partReformData:GetQuality()~=msg.curPart.curEntry[i].quality then
                    index=i
                    break
                end
            elseif type=="配件强化成功" then
                if partReformData:GetLv()~=msg.curPart.curEntry[i].powerlev then
                    index=i
                    break
                end
            end
        end
        if index~=nil then
            print("   alter_val     ",alter_val)
            --local logData = QuickTaData:GetPartReform(
            --        type,
            --        msg.curPart.partinx,
            --        msg.curPart.partid,
            --        msg.curPart.curEntry[index].seq,
            --        msg.curPart.curEntry[index].entryid,
            --        msg.curPart.curEntry[index].quality,
            --        msg.curPart.curEntry[index].powerlev,
            --        alter_val
            --)
            --QuickTa:Get():TrackEvent(TrackEventNames.PartReform, logData)
        else
            print("  TrackPartReformEvent 数据错误 ")
        end
    end).catch(function(ex)
        print("  catch Error",ex)
    end)
end

